from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(11,'longueurs','Longueurs et périmètres','3 · Grandeurs et mesures',
'Unités · Conversions raisonnées · Tour d’une figure',
['Choisir une unité de longueur et convertir en raisonnant.','Estimer une longueur avec des références connues.','Calculer le périmètre d’un polygone.'],
['Nombres décimaux et multiplication par 10 ou 100.'],[
page(1,'Mesurer des longueurs',
bloc('definition',r'Les unités de longueur vont du millimètre au kilomètre : mm, cm, dm, m, km. Relations à connaître : $1\ \mathrm{cm}=10\ \mathrm{mm}$, $1\ \mathrm m=100\ \mathrm{cm}$, $1\ \mathrm m=1\,000\ \mathrm{mm}$ et $1\ \mathrm{km}=1\,000\ \mathrm m$.'),
bloc('savoirfaire',r'Convertir en s’appuyant sur une relation : $3{,}5$ m, c’est $350$ cm, car 1 m vaut 100 cm et $3{,}5\times100=350$. De même, $48$ mm $=4{,}8$ cm, car 10 mm font 1 cm.','Convertir en raisonnant'),
bloc('exemple',r'Des références aident à estimer : une porte mesure environ 2 m, la largeur d’un doigt environ 1 cm, l’épaisseur d’une pièce de monnaie environ 2 mm, un tour de stade 400 m.'),
bloc('attention',r'Avant de comparer ou d’additionner des longueurs, les écrire dans la même unité : $0{,}5$ m et 48 cm se comparent en centimètres, $50>48$.')),
page(2,'Le périmètre d’une figure',
bloc('definition',r'Le périmètre d’une figure est la longueur de son contour. Pour un polygone, on additionne les longueurs de tous les côtés, données ou mesurées à la règle graduée.'),
r'@FIG:cours-perimetre@',
bloc('savoirfaire',r'Le carré a quatre côtés de même longueur : son périmètre est le quadruple du côté. Le rectangle a deux longueurs et deux largeurs : on peut calculer la somme longueur plus largeur, puis la doubler.','Des règles que l’on retrouve'),
bloc('exemple',r'Un rectangle de 8 cm sur $3{,}5$ cm a pour périmètre $8+3{,}5+8+3{,}5=23$ cm. Pour une figure en L, repérer tous les côtés : certains se déduisent des autres avant d’additionner.'))
],[
E('La bonne unité',r'Choisir l’unité adaptée (mm, cm, m ou km) : épaisseur d’une pièce de monnaie ; longueur d’un cahier ; hauteur d’un immeuble ; distance entre deux villes.',r'Épaisseur : $\res{\text{mm}}$. Cahier : $\res{\text{cm}}$. Immeuble : $\res{\text m}$. Distance entre villes : $\res{\text{km}}$.','Associer chaque objet à une référence connue.','assert 10*100==1000'),
E('Convertir en raisonnant',r'Convertir : $3{,}5$ m en cm ; 2 km en m ; 48 mm en cm.',r'$1$ m $=100$ cm, donc $3{,}5$ m $=\res{350}$ cm. $1$ km $=1\,000$ m, donc 2 km $=\res{2\,000}$ m. $10$ mm $=1$ cm, donc 48 mm $=\res{4{,}8}$ cm.','Citer la relation entre les deux unités.','assert Rational("3.5")*100==350 and 2*1000==2000 and Rational(48,10)==Rational("4.8")'),
E('Comparer des longueurs',r'Comparer $0{,}5$ m et 48 cm, puis $1\,200$ m et $1{,}5$ km.',r'$0{,}5$ m $=50$ cm et $50>48$ : $\res{0{,}5\ \mathrm m>48\ \mathrm{cm}}$. $1{,}5$ km $=1\,500$ m : $\res{1\,200\ \mathrm m<1{,}5\ \mathrm{km}}$.','Convertir dans la même unité avant de comparer.','assert Rational(".5")*100==50 and 50>48 and Rational("1.5")*1000==1500 and 1200<1500'),
E('Estimer sans mesurer',r'Associer chaque objet à une longueur : une gomme ; un terrain de football ; la hauteur d’une chaise. Longueurs proposées : 100 m ; 4 cm ; 90 cm.',r'La gomme mesure environ $\res{4\ \mathrm{cm}}$, le terrain $\res{100\ \mathrm m}$, la chaise $\res{90\ \mathrm{cm}}$. Les références évitent les réponses invraisemblables.','Comparer mentalement à des objets connus.','assert 4<90<10000'),
E('Le tour du quadrilatère',r'Calculer le périmètre du quadrilatère dont les côtés mesurent 3 cm, $4{,}5$ cm, $2{,}5$ cm et 4 cm.',r'On additionne les quatre côtés : $3+4{,}5+2{,}5+4=\res{14}$ cm. Regrouper $4{,}5+2{,}5=7$ rend le calcul rapide.','Additionner tous les côtés du contour.','assert 3+Rational("4.5")+Rational("2.5")+4==14',figure='per-5'),
E('Le carré',r'Un carré a des côtés de 7 cm. Calculer son périmètre.',r'Les quatre côtés sont égaux : $4\times7=\res{28}$ cm.','Multiplier le côté par 4.','assert 4*7==28',figure='per-6'),
E('Le rectangle',r'Calculer le périmètre d’un rectangle de longueur 8 cm et de largeur $3{,}5$ cm.',r'Longueur plus largeur : $8+3{,}5=11{,}5$ cm, puis le double : $\res{23}$ cm.','Doubler la somme longueur plus largeur.','assert 2*(8+Rational("3.5"))==23',figure='per-7'),
E('Retrouver le côté',r'Le périmètre d’un carré vaut 36 cm. Quelle est la longueur d’un côté ?',r'Le côté est le quart du périmètre : $36:4=\res9$ cm. Contrôle : $4\times9=36$.','Partager le périmètre en quatre.','assert 36//4==9 and 4*9==36'),
E('Des kilomètres aux mètres',r'Convertir $1{,}25$ km en mètres, puis 230 cm en mètres.',r'$1{,}25\times1\,000=\res{1\,250}$ m. Cent centimètres font un mètre : 230 cm $=\res{2{,}30}$ m, c’est-à-dire $2{,}3$ m.','Multiplier ou partager par la relation entre unités.','assert Rational("1.25")*1000==1250 and Rational(230,100)==Rational("2.3")'),
E('La figure en L',r'Calculer le périmètre de la figure en L, dont les mesures sont indiquées sur le dessin.',r'Les deux côtés sans mesure se déduisent : le petit côté du haut vaut $8-5=3$ cm et le côté vertical intérieur vaut $6-2=4$ cm. Le contour vaut $8+6+5+4+3+2=\res{28}$ cm.','Déduire les côtés manquants avant d’additionner.','assert 8-5==3 and 6-2==4 and 8+6+5+4+3+2==28',figure='per-10'),
E('La clôture du jardin',r'Un jardin rectangulaire mesure $12{,}5$ m sur 8 m. On veut le clôturer en laissant un portail de $1{,}5$ m.'+Q(r'Calculer le périmètre du jardin.',r'Quelle longueur de grillage faut-il acheter ?'),r'Périmètre : $2\times(12{,}5+8)=2\times20{,}5=\res{41}$ m. En retirant le portail : $41-1{,}5=\res{39{,}5}$ m de grillage.','Retirer l’ouverture après le calcul du tour.','assert 2*(Rational("12.5")+8)==41 and 41-Rational("1.5")==Rational("39.5")'),
E('Les tours de piste',r'Une piste d’athlétisme mesure 400 m par tour. Un coureur effectue 5 tours. Quelle distance parcourt-il, en mètres puis en kilomètres ?',r'$400\times5=\res{2\,000}$ m. Comme $1\,000$ m font 1 km : $\res2$ km.','Multiplier la longueur d’un tour, puis convertir.','assert 400*5==2000 and 2000//1000==2'),
E('Deux chemins sur quadrillage',r'Sur le quadrillage, chaque carreau mesure 1 cm de côté. Comparer les périmètres du rectangle et de la figure en escalier.',r'Le rectangle a pour périmètre $2\times(5+3)=16$ cm. En suivant l’escalier, chaque marche remplace un coin sans changer le total horizontal ni vertical : son périmètre vaut aussi $\res{16}$ cm. Deux figures différentes peuvent avoir $\res{\text{le même périmètre}}$.','Compter les déplacements horizontaux et verticaux.','assert 2*(5+3)==16',figure='per-13'),
E('Le cadre de la photo',r'Une photo rectangulaire mesure 15 cm sur 10 cm. On veut coller un ruban sur tout son contour. Le ruban disponible mesure $0{,}45$ m. Suffira-t-il ?',r'Le contour vaut $2\times(15+10)=50$ cm. Le ruban mesure $0{,}45$ m $=45$ cm. Comme $45<50$, il manque $\res5$ cm : le ruban $\res{\text{ne suffit pas}}$.','Tout convertir en centimètres avant de conclure.','assert 2*(15+10)==50 and Rational(".45")*100==45 and 50-45==5'),
E('Même périmètre, même figure ?',r'Lou affirme : « Deux figures qui ont le même périmètre sont forcément identiques. » Trouver un contre-exemple avec un carré et un rectangle.',r'Un carré de côté 4 cm a un périmètre de 16 cm ; un rectangle de 6 cm sur 2 cm aussi : $2\times(6+2)=16$. Les figures sont différentes : l’affirmation est $\res{\text{fausse}}$.','Chercher deux figures différentes de même tour.','assert 4*4==16 and 2*(6+2)==16')
],reperes=['Unités et conversions raisonnées','Estimations et références','Périmètres de polygones','Figures composées et problèmes'],deco='grandeurs')

chapitre(12,'masses-contenances','Masses et contenances','3 · Grandeurs et mesures',
'Grammes · Kilogrammes · Litres · Centilitres',
['Choisir une unité de masse ou de contenance adaptée.','Convertir en s’appuyant sur les relations entre unités.','Résoudre des problèmes de masses et de contenances.'],
['Multiplication par 10, 100, 1 000 et décimaux.'],[
page(1,'Les masses',
bloc('definition',r'Les unités de masse vont du milligramme à la tonne : mg, g, kg, t. Relations à connaître : $1\ \mathrm g=1\,000\ \mathrm{mg}$, $1\ \mathrm{kg}=1\,000\ \mathrm g$ et $1\ \mathrm t=1\,000\ \mathrm{kg}$.'),
bloc('exemple',r'Références utiles : une pièce de 1 euro pèse environ $7{,}5$ g, une pomme environ 150 g, une bouteille d’eau pleine environ $1{,}5$ kg, une petite voiture environ $1{,}2$ t.'),
bloc('savoirfaire',r'$2{,}5$ kg $=2\,500$ g, car 1 kg vaut $1\,000$ g et $2{,}5\times1\,000=2\,500$. Dans l’autre sens, 500 g est la moitié de $1\,000$ g : c’est $0{,}5$ kg.','Convertir des masses'),
bloc('attention',r'Sur une balance à plateaux, l’équilibre compare deux masses : l’objet pèse autant que l’ensemble des masses marquées posées sur l’autre plateau.')),
page(2,'Les contenances',
bloc('definition',r'Les unités de contenance vont du millilitre à l’hectolitre : mL, cL, dL, L, hL. Relations à connaître : $1\ \mathrm L=100\ \mathrm{cL}=1\,000\ \mathrm{mL}$ et $1\ \mathrm{hL}=100\ \mathrm L$.'),
bloc('exemple',r'Références utiles : une cuillère à café contient environ 5 mL, un verre environ 20 cL, une grande bouteille $1{,}5$ L, un seau environ 10 L, une baignoire environ 150 L.'),
bloc('savoirfaire',r'$2$ L $=200$ cL, car 1 L vaut 100 cL. Et 350 cL $=3{,}50$ L, car 100 cL font 1 L : on cherche combien de fois 100 tient dans 350.','Convertir des contenances'),
bloc('attention',r'Comparer des contenances exige la même unité : 75 cL et 1 L se comparent en centilitres, $75<100$. La forme du récipient ne dit pas sa contenance.'))
],[
E('La bonne unité',r'Choisir l’unité adaptée (mg, g, kg, t ou mL, cL, L) : masse d’une gomme ; masse d’un camion chargé ; contenance d’une cuillère ; contenance d’une piscine.',r'Gomme : $\res{\text g}$. Camion : $\res{\text t}$. Cuillère : $\res{\text{mL}}$. Piscine : des milliers de litres, donc $\res{\text L}$ (ou l’hectolitre).','Passer par des objets de référence.','assert 1000*1000==1000000'),
E('Convertir des masses',r'Convertir : 3 kg en g ; $2{,}5$ kg en g ; 500 g en kg.',r'$3\times1\,000=\res{3\,000}$ g et $2{,}5\times1\,000=\res{2\,500}$ g. Pour 500 g : la moitié de $1\,000$ g, soit $\res{0{,}5}$ kg.','Utiliser 1 kg = 1 000 g dans les deux sens.','assert 3*1000==3000 and Rational("2.5")*1000==2500 and Rational(500,1000)==Rational(".5")'),
E('Convertir des contenances',r'Convertir : 2 L en cL ; 350 cL en L ; 5 hL en L.',r'$2\times100=\res{200}$ cL. $350$ cL $=\res{3{,}50}$ L, car 100 cL font 1 L. $5\times100=\res{500}$ L.','Citer la relation utilisée pour chaque conversion.','assert 2*100==200 and Rational(350,100)==Rational("3.5") and 5*100==500'),
E('Comparer',r'Comparer $1{,}2$ kg et 950 g, puis 75 cL et 1 L.',r'$1{,}2$ kg $=1\,200$ g et $1\,200>950$ : $\res{1{,}2\ \mathrm{kg}>950\ \mathrm g}$. $1$ L $=100$ cL et $75<100$ : $\res{75\ \mathrm{cL}<1\ \mathrm L}$.','Convertir dans la plus petite unité.','assert Rational("1.2")*1000==1200 and 1200>950 and 75<100'),
E('Des estimations sensées',r'Associer chaque objet à une mesure : une orange ; un cartable rempli ; une canette de soda ; une baignoire. Mesures proposées : 33 cL ; 150 L ; 200 g ; 7 kg.',r'Orange : $\res{200\ \mathrm g}$. Cartable : $\res{7\ \mathrm{kg}}$. Canette : $\res{33\ \mathrm{cL}}$. Baignoire : $\res{150\ \mathrm L}$.','Éliminer les associations invraisemblables.','assert 200<7000 and 33<15000'),
E('La balance à plateaux',r'Une balance est en équilibre : à gauche, un sac de farine ; à droite, des masses de 500 g, 200 g et 50 g. Quelle est la masse du sac ?',r'L’équilibre signifie l’égalité des masses : $500+200+50=\res{750}$ g.','Additionner les masses marquées.','assert 500+200+50==750',figure='mas-6'),
E('Le colis complet',r'Un colis contient un livre de $1{,}2$ kg et un jeu de 850 g. Calculer la masse totale, en grammes puis en kilogrammes.',r'$1{,}2$ kg $=1\,200$ g ; total : $1\,200+850=\res{2\,050}$ g, soit $\res{2{,}050}$ kg, c’est-à-dire $2{,}05$ kg.','Convertir avant d’additionner.','assert 1200+850==2050 and Rational(2050,1000)==Rational("2.05")'),
E('Des verres bien remplis',r'Une carafe contient $1{,}5$ L de jus. Combien de verres de 25 cL peut-on remplir ?',r'$1{,}5$ L $=150$ cL. On compte de 25 en 25 : $25\times6=150$, donc $\res6$ verres exactement.','Chercher combien de fois 25 tient dans 150.','assert Rational("1.5")*100==150 and 25*6==150'),
E('Le chargement du camion',r'Un camion peut charger 1 t. On pose une palette de 850 kg puis une caisse de 325 kg. Le chargement est-il possible ?',r'$850+325=1\,175$ kg, or 1 t $=1\,000$ kg. Le chargement dépasse de $1\,175-1\,000=\res{175}$ kg : $\res{\text{impossible}}$.','Comparer le total à la tonne convertie.','assert 850+325==1175 and 1175-1000==175'),
E('La recette doublée',r'Une recette demande 250 g de farine. On double la recette, avec un paquet de 1 kg. Quelle masse de farine utilise-t-on et combien en reste-t-il ?',r'Doubler : $250\times2=\res{500}$ g. Le paquet contient $1\,000$ g : il reste $1\,000-500=\res{500}$ g, la moitié du paquet.','Convertir le paquet en grammes.','assert 250*2==500 and 1000-500==500'),
E('Les briques de lait',r'La cantine reçoit 3 packs de 6 briques de 1 L de lait. Elle utilise 15 L dans la semaine. Quelle contenance de lait reste-t-il ?',r'Le stock vaut $3\times6=18$ briques, soit 18 L. Il reste $18-15=\res3$ L, trois briques pleines.','Calculer le stock avant la consommation.','assert 3*6==18 and 18-15==3'),
E('L’ascenseur',r'Un ascenseur accepte 300 kg au plus. Quatre personnes de 72 kg chacune y montent avec un colis de 15 kg. Est-ce autorisé ?',r'Les personnes pèsent $4\times72=288$ kg ; avec le colis : $288+15=\res{303}$ kg. Comme $303>300$, c’est $\res{\text{interdit}}$, à 3 kg près.','Additionner toutes les masses embarquées.','assert 4*72==288 and 288+15==303 and 303>300'),
E('La citerne de l’école',r'Une citerne de récupération d’eau contient 5 hL. On en tire 120 L pour arroser. Quelle contenance d’eau reste-t-il, en litres ?',r'$5$ hL $=500$ L. Il reste $500-120=\res{380}$ L.','Convertir les hectolitres avant de soustraire.','assert 5*100==500 and 500-120==380'),
E('Les pots de confiture',r'Avec $2{,}4$ kg de confiture, combien de pots de 300 g peut-on remplir exactement ?',r'$2{,}4$ kg $=2\,400$ g. En comptant de 300 en 300 : $300\times8=2\,400$, donc $\res8$ pots, sans reste.','Chercher le facteur qui complète 300.','assert Rational("2.4")*1000==2400 and 300*8==2400'),
E('Plumes ou plomb ?',r'Sacha demande : « Qu’est-ce qui est le plus lourd : 1 kg de plumes ou 1 kg de plomb ? » Répondre, puis expliquer pourquoi un litre d’eau est une bonne référence de masse.',r'Les deux pèsent $\res{\text{pareil}}$ : un kilogramme reste un kilogramme, seule la place occupée change. Un litre d’eau pèse environ $\res{1\ \mathrm{kg}}$ : cette référence relie contenances et masses pour estimer.','Distinguer la masse de l’encombrement.','assert 1==1 and 1000*1==1000')
],reperes=['Unités de masse et références','Unités de contenance et références','Conversions raisonnées','Problèmes de masses et de volumes utiles'],deco='grandeurs')
